use vstd::prelude::*;

verus! {

  // Given an input vector `arr` of i32 and an element `elem`,
  // returns a new vector `result` which interleaves `elem`
  // before each entry of `arr`.
  //
  // Post-condition:
  //   1. result.len() == 2 * arr.len()
  //   2. for every k < arr.len(), 
  //        result[2*k]   == elem
  //        result[2*k+1] == arr[k]
  fn insert_before_each(arr: &Vec<i32>, elem: i32) -> (result: Vec<i32>)
    ensures
      // length is doubled
      result.len() == arr.len() * 2,
      // content is interleaved as specified
      (forall |k: nat|
         k < arr.len() as nat ==>
           result@.index(2*k)     == elem
        && result@.index(2*k + 1) == arr@.index(k))
  {
    // Pre-allocate a vector of the right capacity
    let mut result: Vec<i32> = Vec::with_capacity(arr.len() * 2);
    let mut idx: usize = 0;

    // We iterate `idx` from 0 up to arr.len(),
    // maintaining that `result` so far has length 2*idx
    // and satisfies the interleaving property for all k < idx.
    while idx < arr.len()
      invariant
        // 0 <= idx <= arr.len()
        idx <= arr.len(),
        // result length = 2 * idx
        result.len() == idx * 2,
        // for all k < idx, result[2*k] == elem  and  result[2*k+1] == arr[k]
        (forall |k: nat|
           k < idx as nat ==>
             result@.index(2*k)     == elem
          && result@.index(2*k + 1) == arr@.index(k))
      decreases arr.len() - idx,
    {
      // push the interleaved pair
      result.push(elem);
      result.push(arr.index(idx));
      idx = idx + 1;
    }

    result
  }

} // verus!

